package com.camerapoints;

import com.camerapoints.models.CameraPoint;
import com.camerapoints.models.CameraPointGroup;
import net.runelite.client.config.Keybind;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class CameraPointGroupManager
{
	private final List<CameraPointGroup> groups = new ArrayList<>();
	private final Map<Integer, Integer> currentPointIds = new HashMap<>();

	public void setGroups(List<CameraPointGroup> groups)
	{
		this.groups.clear();
		this.groups.addAll(groups);
	}

	public void addGroup(CameraPointGroup group)
	{
		int nextId = groups.stream().map(CameraPointGroup::getId).max(Integer::compareTo).map(i -> i + 1).orElse(0);
		group.setId(nextId);
		groups.add(group);
	}

	public CameraPointGroup addGroup()
	{
		CameraPointGroup newGroup = new CameraPointGroup(-1, "New Group", true, Keybind.NOT_SET, Keybind.NOT_SET, new ArrayList<>());
		addGroup(newGroup);
		return newGroup;
	}

	public void removeGroup(CameraPointGroup group)
	{
		groups.remove(group);
		for (int i = 0; i < groups.size(); i++)
		{
			groups.get(i).setId(i);
		}
	}

	public void moveGroup(CameraPointGroup group, int offset)
	{
		int index = groups.indexOf(group);
		if (index == -1 || index + offset < 0 || index + offset >= groups.size())
		{
			return;
		}

		groups.remove(index);
		groups.add(index + offset, group);
		for (int i = 0; i < groups.size(); i++)
		{
			groups.get(i).setId(i);
		}
	}

	public void addPointToGroup(CameraPointGroup group, CameraPoint point)
	{
		int nextId = group.getPoints().stream().map(CameraPoint::getId).max(Integer::compareTo).map(i -> i + 1).orElse(0);
		point.setId(nextId);
		group.getPoints().add(point);
	}

	public CameraPoint addPointToGroup(CameraPointGroup group)
	{
		int nextId = group.getPoints().stream().map(CameraPoint::getId).max(Integer::compareTo).map(i -> i + 1).orElse(0);
		CameraPoint newPoint = new CameraPoint(nextId, "New Camera Point", CameraPoint.Direction.NORTH, -1, false, Keybind.NOT_SET, true);
		addPointToGroup(group, newPoint);
		return newPoint;
	}

	public void removePointFromGroup(CameraPointGroup group, CameraPoint point)
	{
		group.getPoints().remove(point);
		for (int i = 0; i < group.getPoints().size(); i++)
		{
			group.getPoints().get(i).setId(i);
		}
	}

	public List<CameraPointGroup> getAllGroups()
	{
		return groups.stream().sorted(Comparator.comparingInt(CameraPointGroup::getId)).collect(Collectors.toList());
	}

	public List<CameraPointGroup> getEnabledGroups()
	{
		return groups.stream()
			.filter(CameraPointGroup::isEnabled)
			.sorted(Comparator.comparingInt(CameraPointGroup::getId))
			.collect(Collectors.toList());
	}

	public List<CameraPoint> getAllPointsForGroup(CameraPointGroup group)
	{
		return group.getPoints().stream().sorted(Comparator.comparingInt(CameraPoint::getId)).collect(Collectors.toList());
	}

	public List<CameraPoint> getEnabledPointsForGroup(CameraPointGroup group)
	{
		return group.getPoints().stream()
			.filter(CameraPoint::isEnabled)
			.sorted(Comparator.comparingInt(CameraPoint::getId))
			.collect(Collectors.toList());
	}

	public void updateCycleIndexToPoint(CameraPointGroup group, CameraPoint point)
	{
		currentPointIds.put(group.getId(), point.getId());
	}

	public CameraPoint cycleNext(CameraPointGroup group)
	{
		List<CameraPoint> enabledPoints = group.getPoints().stream().filter(CameraPoint::isEnabled).collect(Collectors.toList());
		if (enabledPoints.isEmpty())
		{
			return null;
		}

		Integer currentPointId = currentPointIds.get(group.getId());
		int currentIndex = -1;
		for (int i = 0; i < enabledPoints.size(); i++)
		{
			if (enabledPoints.get(i).getId() == (currentPointId == null ? Integer.MIN_VALUE : currentPointId))
			{
				currentIndex = i;
				break;
			}
		}
		int nextIndex = currentIndex != -1 ? (currentIndex + 1) % enabledPoints.size() : 0;
		CameraPoint nextPoint = enabledPoints.get(nextIndex);
		currentPointIds.put(group.getId(), nextPoint.getId());
		return nextPoint;
	}

	public CameraPoint cyclePrevious(CameraPointGroup group)
	{
		List<CameraPoint> enabledPoints = group.getPoints().stream().filter(CameraPoint::isEnabled).collect(Collectors.toList());
		if (enabledPoints.isEmpty())
		{
			return null;
		}

		Integer currentPointId = currentPointIds.get(group.getId());
		int currentIndex = -1;
		for (int i = 0; i < enabledPoints.size(); i++)
		{
			if (enabledPoints.get(i).getId() == (currentPointId == null ? Integer.MIN_VALUE : currentPointId))
			{
				currentIndex = i;
				break;
			}
		}
		int previousIndex = currentIndex != -1 ? (currentIndex - 1 + enabledPoints.size()) % enabledPoints.size() : enabledPoints.size() - 1;
		CameraPoint previousPoint = enabledPoints.get(previousIndex);
		currentPointIds.put(group.getId(), previousPoint.getId());
		return previousPoint;
	}
}

package com.camerapoints;

import com.google.common.base.Strings;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.input.KeyListener;

import javax.inject.Inject;
import java.awt.KeyEventDispatcher;
import java.awt.event.KeyEvent;

public class KeyHandler implements KeyListener
{
	@Inject
	private CameraPointsPlugin plugin;

	@Inject
	private Client client;

	@Inject
	private CameraPointsConfig config;

	private boolean typing = false;

	private final KeyEventDispatcher keyEventDispatcher = new KeyEventDispatcher()
	{
		@Override
		public boolean dispatchKeyEvent(KeyEvent e)
		{
			if (!chatboxFocused())
			{
				return false;
			}

			if (typing && e != null && e.getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				typing = false;
				return false;
			}

			return false;
		}
	};

	public KeyEventDispatcher getKeyEventDispatcher()
	{
		return keyEventDispatcher;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if ((!typing && !isDialogOpen()) || !config.disableWhileTyping())
		{
			if (plugin.handleCameraPointChange(e))
			{
				return;
			}
		}

		if (!chatboxFocused())
		{
			return;
		}

		if (!typing)
		{
			if (e != null)
			{
				int code = e.getKeyCode();
				if (code == KeyEvent.VK_ENTER || code == KeyEvent.VK_SLASH || code == KeyEvent.VK_COLON)
				{
					typing = true;
				}
			}
			return;
		}

		if (e == null)
		{
			return;
		}

		if (e.getKeyCode() == KeyEvent.VK_ENTER)
		{
			typing = false;
		}
		else if (e.getKeyCode() == KeyEvent.VK_BACK_SPACE && Strings.isNullOrEmpty(client.getVarcStrValue(VarClientID.CHATINPUT)))
		{
			typing = false;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	public boolean chatboxFocused()
	{
		net.runelite.api.widgets.Widget chatboxParent = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (chatboxParent == null || chatboxParent.getOnKeyListener() == null)
		{
			return false;
		}

		net.runelite.api.widgets.Widget worldMapSearch = client.getWidget(InterfaceID.Worldmap.MAPLIST_DISPLAY);
		if (worldMapSearch != null && client.getVarcIntValue(VarClientID.WORLDMAP_SEARCHING) == 1)
		{
			return false;
		}

		net.runelite.api.widgets.Widget report = client.getWidget(InterfaceID.Reportabuse.UNIVERSE);
		if (report != null)
		{
			return false;
		}

		return true;
	}

	public boolean isDialogOpen()
	{
		return isHidden(InterfaceID.Chatbox.MES_LAYER_HIDE)
			|| isHidden(InterfaceID.Chatbox.CHATDISPLAY)
			|| !isHidden(InterfaceID.BankpinKeypad.UNIVERSE);
	}

	private boolean isHidden(int component)
	{
		net.runelite.api.widgets.Widget w = client.getWidget(component);
		return w == null || w.isSelfHidden();
	}
}

package com.camerapoints;

import com.camerapoints.models.CameraPoint;
import com.camerapoints.models.CameraPointGroup;
import com.camerapoints.migrations.ConfigMigrationRunner;
import com.camerapoints.ui.CameraPointsPluginPanel;
import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.KeyboardFocusManager;
import java.awt.event.KeyEvent;
import java.util.Arrays;
import java.util.List;

@Slf4j
@PluginDescriptor(
	name = "Camera Points"
)
public class CameraPointsPlugin extends Plugin
{
	public static final String CURRENT_VERSION = "3.0.1";
	public static final int SCRIPTID_CAM_FORCE_ANGLE = 143;
	public static final int SCRIPTID_COMPASS_ANGLE = 1050;

	@Inject
	private Gson gson;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private CameraPointsConfig cameraPointsConfig;

	@Inject
	private ConfigManager configManager;

	@Inject
	CameraPointGroupManager cameraPointGroupManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private KeyHandler keyHandler;

	@Inject
	private ConfigMigrationRunner configMigrationRunner;

	private CameraPointsPluginPanel pluginPanel;
	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		keyManager.registerKeyListener(keyHandler);
		KeyboardFocusManager.getCurrentKeyboardFocusManager().addKeyEventDispatcher(keyHandler.getKeyEventDispatcher());
		loadConfig();
		pluginPanel = new CameraPointsPluginPanel(this);

		navigationButton = NavigationButton.builder()
			.tooltip("Camera Points")
			.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
			.priority(5)
			.panel(pluginPanel)
			.build();
		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(keyHandler);
		KeyboardFocusManager.getCurrentKeyboardFocusManager().removeKeyEventDispatcher(keyHandler.getKeyEventDispatcher());
		clientToolbar.removeNavigation(navigationButton);
		pluginPanel = null;
	}

	public boolean handleCameraPointChange(KeyEvent keyEvent)
	{
		for (CameraPointGroup cameraPointGroup : cameraPointGroupManager.getEnabledGroups())
		{
			if (cameraPointGroup.getNextKeybind().matches(keyEvent))
			{
				CameraPoint nextCamera = cameraPointGroupManager.cycleNext(cameraPointGroup);
				if (nextCamera != null)
				{
					setCamera(nextCamera);
					return true;
				}
			}
			if (cameraPointGroup.getPreviousKeybind().matches(keyEvent))
			{
				CameraPoint prevCamera = cameraPointGroupManager.cyclePrevious(cameraPointGroup);
				if (prevCamera != null)
				{
					setCamera(prevCamera);
					return true;
				}
			}
			for (CameraPoint cameraPoint : cameraPointGroupManager.getEnabledPointsForGroup(cameraPointGroup))
			{
				if (cameraPoint.getKeybind().matches(keyEvent))
				{
					setCamera(cameraPoint);
					cameraPointGroupManager.updateCycleIndexToPoint(cameraPointGroup, cameraPoint);
					return true;
				}
			}
		}
		return false;
	}

	public void setCamera(CameraPoint cameraPoint)
	{
		clientThread.invoke(() -> {
			var direction = cameraPoint.getDirection() == null ? CameraPoint.Direction.NONE : cameraPoint.getDirection();
			if (direction != CameraPoint.Direction.NONE)
			{
				client.runScript(SCRIPTID_COMPASS_ANGLE, direction.getScriptValue());
			}
			if (cameraPoint.isApplyZoom())
			{
				client.runScript(ScriptID.CAMERA_DO_ZOOM, cameraPoint.getZoom(), cameraPoint.getZoom());
			}
		});
	}

	public void saveCameraPosition(CameraPoint cameraPoint)
	{
		cameraPoint.setDirection(CameraPoint.Direction.fromCameraYaw(client.getCameraYaw()));
		cameraPoint.setZoom(getCurrentZoom());
		cameraPoint.setApplyZoom(true);
	}

	public int getCurrentZoom()
	{
		return client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);
	}

	public CameraPoint addPointToGroup(CameraPointGroup group)
	{
		CameraPoint point = cameraPointGroupManager.addPointToGroup(group);
		point.setZoom(getCurrentZoom());
		point.setApplyZoom(true);
		return point;
	}

	public void updateCameraPointZoom(CameraPoint cameraPoint)
	{
		cameraPoint.setZoom(getCurrentZoom());
		cameraPoint.setApplyZoom(true);
	}

	public void loadConfig()
	{
		configMigrationRunner.runMigrations(CURRENT_VERSION);

		String groupsJson = configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "groups");
		CameraPointGroup[] groups = gson.fromJson(groupsJson, CameraPointGroup[].class);
		List<CameraPointGroup> groupList = groups == null ? java.util.Collections.emptyList() : Arrays.asList(groups);
		cameraPointGroupManager.setGroups(groupList);
	}

	public void updateConfig()
	{
		configManager.setConfiguration(CameraPointsConfig.CONFIG_GROUP, "version", CURRENT_VERSION);
		configManager.setConfiguration(CameraPointsConfig.CONFIG_GROUP, "groups", gson.toJson(cameraPointGroupManager.getAllGroups()));
	}

	public CameraPointGroupManager getCameraPointGroupManager()
	{
		return cameraPointGroupManager;
	}

	@Provides
	CameraPointsConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CameraPointsConfig.class);
	}
}

package com.camerapoints.models;

import net.runelite.client.config.Keybind;

import java.util.Objects;

public class CameraPoint
{
	public enum Direction
	{
		NONE(0, "Unchanged"),
		NORTH(1, "North"),
		EAST(2, "East"),
		SOUTH(3, "South"),
		WEST(4, "West");

		private final int scriptValue;
		private final String displayName;

		Direction(int scriptValue, String displayName)
		{
			this.scriptValue = scriptValue;
			this.displayName = displayName;
		}

		public int getScriptValue()
		{
			return scriptValue;
		}

		public static Direction fromCameraYaw(int yaw)
		{
			int normalized = ((yaw % 2048) + 2048) % 2048;
			if (normalized < 256 || normalized >= 1792)
			{
				return SOUTH;
			}
			if (normalized < 768)
			{
				return WEST;
			}
			if (normalized < 1280)
			{
				return NORTH;
			}
			return EAST;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	private int id;
	private String name;
	private Direction direction;
	private int zoom;
	private boolean applyZoom;
	private Keybind keybind;
	private boolean enabled;

	public CameraPoint(int id, String name, Direction direction, int zoom, boolean applyZoom, Keybind keybind, boolean enabled)
	{
		this.id = id;
		this.name = name;
		this.direction = direction;
		this.zoom = zoom;
		this.applyZoom = applyZoom;
		this.keybind = keybind;
		this.enabled = enabled;
	}

	public int getId()
	{
		return id;
	}

	public void setId(int id)
	{
		this.id = id;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public Direction getDirection()
	{
		return direction;
	}

	public void setDirection(Direction direction)
	{
		this.direction = direction;
	}

	public int getZoom()
	{
		return zoom;
	}

	public void setZoom(int zoom)
	{
		this.zoom = zoom;
	}

	public boolean isApplyZoom()
	{
		return applyZoom;
	}

	public void setApplyZoom(boolean applyZoom)
	{
		this.applyZoom = applyZoom;
	}

	public Keybind getKeybind()
	{
		return keybind;
	}

	public void setKeybind(Keybind keybind)
	{
		this.keybind = keybind;
	}

	public boolean isEnabled()
	{
		return enabled;
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		CameraPoint that = (CameraPoint) o;
		return id == that.id
			&& zoom == that.zoom
			&& applyZoom == that.applyZoom
			&& enabled == that.enabled
			&& Objects.equals(name, that.name)
			&& direction == that.direction
			&& Objects.equals(keybind, that.keybind);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id, name, direction, zoom, applyZoom, keybind, enabled);
	}

	@Override
	public String toString()
	{
		return "CameraPoint{" +
			"id=" + id +
			", name='" + name + '\'' +
			", direction=" + direction +
			", zoom=" + zoom +
			", applyZoom=" + applyZoom +
			", keybind=" + keybind +
			", enabled=" + enabled +
			'}';
	}
}

