package com.camerapoints.migrations;

import com.camerapoints.CameraPointsConfig;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

@Slf4j
public class ConfigMigrationRunner
{
	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public ConfigMigrationRunner(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void runMigrations(String targetVersion)
	{
		String configVersion = configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "version");
		if (targetVersion.equals(configVersion))
		{
			return;
		}

		List<ConfigMigration> migrations = loadMigrations();
		if (migrations.isEmpty())
		{
			log.warn("No config migrations configured for {} -> {}", configVersion, targetVersion);
			return;
		}

		String runningVersion = configVersion;
		boolean appliedAny = false;
		for (ConfigMigration migration : migrations)
		{
			if (!Objects.equals(migration.fromVersion(), runningVersion))
			{
				continue;
			}
			if (!applyMigration(migration))
			{
				return;
			}
			runningVersion = configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "version");
			appliedAny = true;
		}

		if (!targetVersion.equals(runningVersion))
		{
			if (!appliedAny)
			{
				log.warn("No config migration path found from {} to {}", configVersion, targetVersion);
			}
			else
			{
				log.warn("Incomplete config migration path from {} to {}. Last migrated version: {}", configVersion, targetVersion, runningVersion);
			}
			return;
		}

	}

	private boolean applyMigration(ConfigMigration migration)
	{
		log.info("Applying camera points config migration {} -> {}", migration.fromVersion(), migration.toVersion());
		try
		{
			migration.apply(configManager, gson);
			return true;
		}
		catch (RuntimeException ex)
		{
			log.error(
				"Failed camera points config migration {} -> {}. Config snapshot: version={}, groups={}",
				migration.fromVersion(),
				migration.toVersion(),
				configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "version"),
				configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "groups"),
				ex
			);
			return false;
		}
	}

	private List<ConfigMigration> loadMigrations()
	{
		return Collections.unmodifiableList(List.of(
			new GroupMigrate(),
			new GroupMigrateRecovery()
		));
	}
}

package com.camerapoints.migrations;

import com.camerapoints.CameraPointsConfig;
import com.camerapoints.models.CameraPoint;
import com.camerapoints.models.CameraPointGroup;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class GroupMigrateRecovery implements ConfigMigration
{
	@Override
	public String fromVersion()
	{
		return "3.0.0";
	}

	@Override
	public String toVersion()
	{
		return "3.0.1";
	}

	@Override
	public void apply(ConfigManager configManager, Gson gson)
	{
		String oldPointsJson = configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "points");
		if (oldPointsJson != null && !oldPointsJson.isEmpty())
		{
			JsonArray pointsArray = new JsonParser().parse(oldPointsJson).getAsJsonArray();
			for (int i = 0; i < pointsArray.size(); i++)
			{
				JsonElement pointElement = pointsArray.get(i);
				if (!pointElement.isJsonObject())
				{
					continue;
				}
				JsonObject pointObject = pointElement.getAsJsonObject();
				// Force IDs to 0..n-1 so legacy long values cannot overflow int fields.
				pointObject.addProperty("id", i);
			}

			CameraPoint[] oldPoints = gson.fromJson(pointsArray, CameraPoint[].class);
			if (oldPoints != null && oldPoints.length > 0)
			{
				for (CameraPoint oldPoint : oldPoints)
				{
					oldPoint.setEnabled(true);
				}

				String existingGroupsJson = configManager.getConfiguration(CameraPointsConfig.CONFIG_GROUP, "groups");
				CameraPointGroup[] existingGroupsArray = gson.fromJson(existingGroupsJson, CameraPointGroup[].class);
				List<CameraPointGroup> existingGroups = existingGroupsArray == null
					? new ArrayList<>()
					: new ArrayList<>(Arrays.asList(existingGroupsArray));
				int nextGroupId = existingGroups.stream()
					.map(CameraPointGroup::getId)
					.max(Integer::compareTo)
					.map(id -> id + 1)
					.orElse(0);

				CameraPointGroup recoveredGroup = new CameraPointGroup(
					nextGroupId,
					"Old",
					true,
					Keybind.NOT_SET,
					Keybind.NOT_SET,
					oldPoints == null ? Collections.emptyList() : Arrays.asList(oldPoints)
				);
				existingGroups.add(recoveredGroup);
				configManager.setConfiguration(
					CameraPointsConfig.CONFIG_GROUP,
					"groups",
					gson.toJson(existingGroups)
				);
			}
		}
		configManager.setConfiguration(CameraPointsConfig.CONFIG_GROUP, "version", toVersion());
	}
}

